  "implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    if not attempts:
        return {'decision': 'continue', 'memory_append': None, 'next_attempt': 1}
    last = attempts[-1]
    if any(a['success'] for a in attempts):
        return {'decision': 'stop', 'memory_append': None, 'next_attempt': 0}
    num_attempts = len(attempts)
    if num_attempts < max_attempts:
        return {'decision': 'continue', 'memory_append': {'reflection': last['reflection'], 'signature': last['failure_signature']}, 'next_attempt': num_attempts + 1}
    else:
        return {'decision': 'stop', 'memory_append': None, 'next_attempt': 0}"
}
